/* Comissões · Campanha Meias — módulo atualizado (origem: sistema-de-auditoria, PR #58).
   O portal baixa o sistema do Supabase (portal-file/PORTAL_ESPOSENDE_V4_AUTH.html); este patch troca
   só o módulo "mei" (MENC.mei) antes de ele ser aberto. Novidades:
   - CPF único no pagamento: quem está em mais de um cargo fica só no cargo maior
     (Regional > Gerente > Subgerente > Vendedor/Caixa) e recebe ali o total; mesmo cargo em
     lojas diferentes vira uma linha só. Aba "CPF em Mais de um Cargo" + aba CPF-CARGOS no Excel.
   - Gerente: 50% das vendas da loja ÷ quantidade de gerentes da loja.
   - Leitura de valores "167.00"/"167,00" e CSV em UTF-8 (o upload-correcoes.js segue valendo).
   Para voltar ao módulo anterior: remova a linha do meias-modulo-patch.js no index.html. */
(function(){
  var B64="";
  function aplicar(){
    if(typeof MENC==='undefined')return false;
    MENC.mei=B64;
    try{if(typeof BLOBS!=='undefined'&&BLOBS.mei){URL.revokeObjectURL(BLOBS.mei);delete BLOBS.mei;}}catch(e){}
    window.__MEIAS_MODULO_VERSAO='20261104-pr58';
    return true;
  }
  if(!aplicar())document.addEventListener('DOMContentLoaded',aplicar);
})();
